<tr><td>NVIC_PRIORITYGROUP_4</td><td>4</td><td>0</td><td>16 \u7EA7\u62A2\u5360\uFF0C\u6700\u7075\u6D3B\uFF0C\u4F46\u4E0D\u80FD\u7528\u5B50\u4F18\u5148\u7EA7\u7EC6\u5206</td></tr>
